async (page) => {
const urls=['/','/entites/ENT-A','/chaine','/agent','/avant-apres','/pseudonymisation','/outillage'];
const out=[];const reqs=[];
page.on('request',r=>reqs.push(r.url()));
for(const u of urls){
const resp=await page.goto('http://127.0.0.1:8765'+u);
const d=await page.evaluate(()=>({title:document.title,h1:[...document.querySelectorAll('h1')].map(h=>h.textContent.trim()),lang:document.documentElement.lang,cur:[...document.querySelectorAll('[aria-current="page"]')].map(e=>e.textContent.trim()+'|'+e.getAttribute('href')),btn:[...document.querySelectorAll('header a,header button')].map(e=>e.textContent.trim()).filter(t=>t),header:(document.querySelector('header')||{}).innerText,body:document.body.innerText.slice(0,500)}));
out.push({u,status:resp.status(),...d});}
return {out,hosts:[...new Set(reqs.map(r=>new URL(r).host))],n:reqs.length};
}

